+(function() {
+  'use strict';
+
+  const STORAGE_KEY = 'desk-tool-ui-state-v1';
+  let state = {};
+  let isInitialized = false;
+
+  function init() {
+    if (isInitialized) return;
+    loadState();
+    render();
+    bindEvents();
+    isInitialized = true;
+  }
+
+  function loadState() {
+    try {
+      const raw = localStorage.getItem(STORAGE_KEY);
+      if (raw) {
+        state = JSON.parse(raw);
+      } else {
+        state = {
+          notes: [],
+          theme: 'light',
+          sidebarOpen: true,
+          lastNoteId: 0
+        };
+      }
+    } catch (e) {
+      console.warn('Failed to load state:', e);
+      state = {
+        notes: [],
+        theme: 'light',
+        sidebarOpen: true,
+        lastNoteId: 0
+      };
+    }
+  }
+
+  function saveState() {
+    try {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
+    } catch (e) {
+      console.warn('Failed to save state:', e);
+    }
+  }
+
+  function bindEvents() {
+    const noteInput = document.getElementById('note-input');
+    const addBtn = document.getElementById('add-btn');
+    const themeToggle = document.getElementById('theme-toggle');
+    const sidebarToggle = document.getElementById('sidebar-toggle');
+    const notesList = document.getElementById('notes-list');
+
+    addBtn.addEventListener('click', () => {
+      if (!noteInput.value.trim()) return;
+      addNote(noteInput.value.trim());
+      noteInput.value = '';
+      saveState();
+    });
+
+    noteInput.addEventListener('keydown', (e) => {
+      if (e.key === 'Enter') {
+        addBtn.click();
+      }
+    });
+
+    themeToggle.addEventListener('click', () => {
+      state.theme = state.theme === 'light' ? 'dark' : 'light';
+      document.body.setAttribute('data-theme', state.theme);
+      saveState();
+    });
+
+    sidebarToggle.addEventListener('click', () => {
+      state.sidebarOpen = !state.sidebarOpen;
+      document.getElementById('sidebar').classList.toggle('open', state.sidebarOpen);
+      saveState();
+    });
+
+    notesList.addEventListener('click', (e) => {
+      const noteEl = e.target.closest('.note-item');
+      if (!noteEl) return;
+      const id = parseInt(noteEl.dataset.id, 10);
+      const note = state.notes.find(n => n.id === id);
+      if (note) {
+        noteInput.value = note.content;
+      }
+    });
+
+    notesList.addEventListener('dblclick', (e) => {
+      const noteEl = e.target.closest('.note-item');
+      if (!noteEl) return;
+      const id = parseInt(noteEl.dataset.id, 10);
+      const note = state.notes.find(n => n.id === id);
+      if (note) {
+        deleteNote(id);
+        saveState();
+      }
+    });
+
+    notesList.addEventListener('contextmenu', (e) => {
+      e.preventDefault();
+      const noteEl = e.target.closest('.note-item');
+      if (!noteEl) return;
+      const id = parseInt(noteEl.dataset.id, 10);
+      const note = state.notes.find(n => n.id === id);
+      if (note) {
+        editNote(id);
+      }
+    });
+
+    notesList.addEventListener('dragstart', (e) => {
+      e.dataTransfer.setData('text/plain', e.target.dataset.id);
+      e.target.classList.add('dragging');
+    });
+
+    notesList.addEventListener('dragend', () => {
+      const dragging = document.querySelector('.dragging');
+      if (dragging) dragging.classList.remove('dragging');
+    });
+
+    notesList.addEventListener('dragover', (e) => {
+      e.preventDefault();
+      const target = e.target.closest('.note-item');
+      if (!target || !e.dataTransfer.getData('text/plain')) return;
+      const sourceId = parseInt(e.dataTransfer.getData('text/plain'), 10);
+      const targetId = parseInt(target.dataset.id, 10);
+      const sourceIndex = state.notes.findIndex(n => n.id === sourceId);
+      const targetIndex = state.notes.findIndex(n => n.id === targetId);
+      if (sourceIndex < 0 || targetIndex < 0) return;
+      const item = state.notes.splice(sourceIndex, 1)[0];
+      state.notes.splice(targetIndex + (targetIndex < sourceIndex ? -1 : 0), 0, item);
+      render();
+      saveState();
+    });
+
+    notesList.addEventListener('drop', (e) => {
+      e.preventDefault();
+      const target = e.target.closest('.note-item');
+      if (!target) return;
+      const sourceId = parseInt(e.dataTransfer.getData('text/plain'), 10);
+      const targetId = parseInt(target.dataset.id, 10);
+      const sourceIndex = state.notes.findIndex(n => n.id === sourceId);
+      const targetIndex = state.notes.findIndex(n => n.id === targetId);
+      if (sourceIndex < 0 || targetIndex < 0) return;
+      const item = state.notes.splice(sourceIndex, 1)[0];
+      state.notes.splice(targetIndex + (targetIndex < sourceIndex ? -1 : 0), 0, item);
+      render();
+      saveState();
+    });
+
+    notesList.addEventListener('dragleave', () => {
+      const dragging = document.querySelector('.dragging');
+      if (dragging) dragging.classList.remove('dragging');
+    });
+  }
+
+  function addNote(content) {
+    state.lastNoteId++;
+    state.notes.push({
+      id: state.lastNoteId,
+      content: content,
+      createdAt: Date.now()
+    });
+    render();
+  }
+
+  function deleteNote(id) {
+    state.notes = state.notes.filter(n => n.id !== id);
+    if (state.notes.length === 0) {
+      noteInput.value = '';
+    }
+    render();
+  }
+
+  function editNote(id) {
+    const note = state.notes.find(n => n.id === id);
+    if (!note) return;
+    noteInput.value = note.content;
+    noteInput.focus();
+  }
+
+  function render() {
+    const notesList = document.getElementById('notes-list');
+    const themeToggle = document.getElementById('theme-toggle');
+    const sidebarToggle = document.getElementById('sidebar-toggle');
+    const noteInput = document.getElementById('note-input');
+    const addBtn = document.getElementById('add-btn');
+
+    notesList.innerHTML = '';
+    state.notes.forEach(note => {
+      const item = document.createElement('div');
+      item.className = 'note-item';
+      item.dataset.id = note.id;
+      item.draggable = true;
+      item.innerHTML = `
+        <span class="note-content">${escapeHtml(note.content)}</span>
+        <button class="delete-btn" aria-label="Delete note">&times;</button>
+      `;
+      item.querySelector('.delete-btn').addEventListener('click', () => {
+        deleteNote(note.id);
+      });
+      notesList.appendChild(item);
+    });
+
+    if (state.notes.length === 0) {
+      const empty = document.createElement('div');
+      empty.className = 'empty-state';
+      empty.textContent = 'No notes yet. Add one above.';
+      notesList.appendChild(empty);
+    }
+
+    themeToggle.setAttribute('aria-label', `Switch to ${state.theme === 'light' ? 'dark' : 'light'} mode`);
+    sidebarToggle.setAttribute('aria-expanded', state.sidebarOpen.toString());
+  }
+
+  function escapeHtml(text) {
+    const div = document.createElement('div');
+    div.textContent = text;
+    return div.innerHTML;
+  }
+
+  // Initialize on DOM ready
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+})();

